1	package reconcile
2	
3	import (
4		"fmt"
5		"path/filepath"
6		"regexp"
7		"strings"
8		"time"
9	
10		"github.com/cameronsjo/bosun/internal/log"
11	)
12	
13	// DefaultTargetName is the name used for the implicit single-target backwards-compat target.
14	const DefaultTargetName = "default"
15	
16	// DefaultLockFile is the default path for the reconciliation lock file.
17	const DefaultLockFile = "/var/run/bosun/reconcile.lock"
18	
19	// DefaultLockDir is the default directory for per-target lock files.
20	const DefaultLockDir = "/var/run/bosun"
21	
22	// Target describes a single deployment target (a server/host to deploy to).
23	// Each target has its own host, appdata paths, project name, state file,
24	// staging directory, secrets scope, and operational overrides.
25	type Target struct {
26		// Name identifies this target (e.g., "unraid", "pi"). Used in file paths and logs.
27		Name string `json:"name"`
28		// TargetHost is empty for local deployment, or "user@host" for remote.
29		TargetHost string `json:"target_host,omitempty"`
30		// LocalAppdataPath is the path to appdata when running locally.
31		LocalAppdataPath string `json:"local_appdata_path,omitempty"`
32		// RemoteAppdataPath is the path to appdata on the remote host.
33		RemoteAppdataPath string `json:"remote_appdata_path,omitempty"`
34		// ProjectName is the docker compose project name for this target.
35		ProjectName string `json:"project_name,omitempty"`
36		// StateFile overrides the derived state file path. When empty, derived from Name.
37		StateFile string `json:"state_file,omitempty"`
38		// StagingDir overrides the derived staging directory. When empty, derived from Name.
39		StagingDir string `json:"staging_dir,omitempty"`
40		// SecretsScope is the key prefix for per-target secrets (e.g., "unraid" -> targets.unraid.*).
41		SecretsScope string `json:"secrets_scope,omitempty"`
42		// CriticalContainers overrides the global list for this target.
43		CriticalContainers []string `json:"critical_containers,omitempty"`
44		// PostSyncHooks overrides the global hooks for this target.
45		PostSyncHooks []PostSyncHook `json:"post_sync_hooks,omitempty"`
46		// DeploySyncPaths overrides the global allowlist for this target.
47		DeploySyncPaths []string `json:"deploy_sync_paths,omitempty"`
48		// DeploySyncExclude overrides the global blocklist for this target.
49		DeploySyncExclude []string `json:"deploy_sync_exclude,omitempty"`
50	}
51	
52	// IsDefault returns true if this is the implicit default target.
53	func (t Target) IsDefault() bool {
54		return t.Name == DefaultTargetName
55	}
56	
57	// ConfigForTarget returns a shallow copy of the base config with per-target
58	// fields (TargetHost, appdata paths, ProjectName, StagingDir, StateFile,
59	// LockFile, CriticalContainers, PostSyncHooks, DeploySyncPaths/Exclude)
60	// overridden from the given Target. This lets the existing pipeline run
61	// unchanged per-target - the daemon creates a ConfigForTarget copy before
62	// each reconciler instantiation.
63	func (c *Config) ConfigForTarget(t Target) *Config {
64		cp := *c // shallow copy
65	
66		// Override per-target fields.
67		cp.TargetName = t.Name
68		cp.TargetHost = t.TargetHost
69		if t.LocalAppdataPath != "" {
70			cp.LocalAppdataPath = t.LocalAppdataPath
71		}
72		if t.RemoteAppdataPath != "" {
73			cp.RemoteAppdataPath = t.RemoteAppdataPath
74		}
75		if t.ProjectName != "" {
76			cp.ProjectName = t.ProjectName
77		}
78	
79		// Derive per-target paths from the base config's directories,
80		// preserving any custom paths the caller configured.
81		// For the default (implicit) target, keep the original paths unchanged
82		// so the daemon/CLI share the same lock and state files as pre-multi-target.
83		if !t.IsDefault() {
84			stateDir := filepath.Dir(c.StateFile)
85			cp.StateFile = TargetStateFile(stateDir, t)
86			cp.StagingDir = TargetStagingDir(c.StagingDir, t)
87			lockDir := filepath.Dir(c.LockFile)
88			cp.LockFile = TargetLockFile(lockDir, t)
89		}
90	
91		// Deep-copy all slices so the returned config has independent backing arrays.
92		// Both inherited slices (from base) and overrides (from target) are cloned
93		// to prevent mutation of either source.
94		// Use nil checks (not len > 0) so targets can explicitly clear inherited
95		// slices with an empty list (e.g., critical_containers: []).
96		if t.CriticalContainers != nil {
97			cp.CriticalContainers.Value = append([]string(nil), t.CriticalContainers...)
98		} else if cp.CriticalContainers.Value != nil {
99			cp.CriticalContainers.Value = append([]string(nil), cp.CriticalContainers.Value...)
100		}
101		if t.PostSyncHooks != nil && !cp.PostSyncHooks.FromEnv() {
102			cp.PostSyncHooks.Value = clonePostSyncHooks(t.PostSyncHooks)
103		} else if cp.PostSyncHooks.Value != nil {
104			cp.PostSyncHooks.Value = clonePostSyncHooks(cp.PostSyncHooks.Value)
105		}
106		if t.DeploySyncPaths != nil {
107			cp.DeploySyncPaths.Value = append([]string(nil), t.DeploySyncPaths...)
108		} else if cp.DeploySyncPaths.Value != nil {
109			cp.DeploySyncPaths.Value = append([]string(nil), cp.DeploySyncPaths.Value...)
110		}
111		if t.DeploySyncExclude != nil {
112			cp.DeploySyncExclude.Value = append([]string(nil), t.DeploySyncExclude...)
113		} else if cp.DeploySyncExclude.Value != nil {
114			cp.DeploySyncExclude.Value = append([]string(nil), cp.DeploySyncExclude.Value...)
115		}
116	
117		if t.SecretsScope != "" {
118			cp.SecretsScope = t.SecretsScope
119		}
120	
121		return &cp
122	}
123	
124	// clonePostSyncHooks returns a deep copy of a PostSyncHook slice,
125	// including each hook's Paths slice.
126	func clonePostSyncHooks(hooks []PostSyncHook) []PostSyncHook {
127		cloned := make([]PostSyncHook, len(hooks))
128		for i, h := range hooks {
129			cloned[i] = h
130			if h.Paths != nil {
131				cloned[i].Paths = append([]string(nil), h.Paths...)
132			}
133			if h.Command != nil {
134				cloned[i].Command = append([]string(nil), h.Command...)
135			}
136		}
137		return cloned
138	}
139	
140	// DefaultConfig returns a Config with sensible defaults.
141	func DefaultConfig() *Config {
142		return &Config{
143			RepoBranch:            "main",
144			RepoDir:               "/app/repo",
145			StagingDir:            "/app/staging",
146			BackupDir:             "/app/backups",
147			LogDir:                "/app/logs",
148			LockFile:              DefaultLockFile,
149			StateFile:             filepath.Join(DefaultStateDir, DefaultStateFile),
150			LocalAppdataPath:      "/mnt/appdata",
151			RemoteAppdataPath:     "/mnt/user/appdata",
152			InfraSubDir:           ".",
153			BackupsToKeep:         5,
154			HealthCheckTimeout:    60 * time.Second,
155			HealthCheckInterval:   5 * time.Second,
156			RestartBreakerEnabled: true,
157			RestartThreshold:      5,
158			RestartWindow:         10 * time.Minute,
159			OnFailure:             true,
160			RemoveOrphans:         NewConfigField(true),
161			HealthGateTimeout:     60 * time.Second,
162		}
163	}
164	
165	// ResolveTargets returns the effective target list for this config.
166	// When Targets is non-empty, returns it as-is.
167	// When Targets is empty, synthesizes a single implicit default target
168	// from the flat config fields for backwards compatibility.
169	func (c *Config) ResolveTargets() []Target {
170		if len(c.Targets) > 0 {
171			// Validate target names and reject duplicates to prevent path collisions.
172			valid := make([]Target, 0, len(c.Targets))
173			seen := make(map[string]bool, len(c.Targets))
174			for _, t := range c.Targets {
175				if t.Name == DefaultTargetName {
176					log.Warn().Str("target", t.Name).Msg("Skipping target: reserved name (used internally for implicit single-target mode)")
177					continue
178				}
179				if err := ValidateTargetName(t.Name); err != nil {
180					log.Warn().Str("target", t.Name).Err(err).Msg("Skipping target with invalid name")
181					continue
182				}
183				lower := strings.ToLower(t.Name)
184				if seen[lower] {
185					log.Warn().Str("target", t.Name).Msg("Skipping duplicate target name (case-insensitive)")
186					continue
187				}
188				seen[lower] = true
189				valid = append(valid, t)
190			}
191			if len(valid) > 0 {
192				return valid
193			}
194			// All configured targets had invalid names — fall through to implicit default.
195			log.Warn().Int("configured", len(c.Targets)).Msg("All configured targets have invalid names, falling back to default target")
196		}
197		return []Target{
198			{
199				Name:               DefaultTargetName,
200				TargetHost:         c.TargetHost,
201				LocalAppdataPath:   c.LocalAppdataPath,
202				RemoteAppdataPath:  c.RemoteAppdataPath,
203				ProjectName:        c.ProjectName,
204				StateFile:          c.StateFile,
205				StagingDir:         c.StagingDir,
206				CriticalContainers: c.CriticalContainers.Value,
207				PostSyncHooks:      c.PostSyncHooks.Value,
208				DeploySyncPaths:    c.DeploySyncPaths.Value,
209				DeploySyncExclude:  c.DeploySyncExclude.Value,
210			},
211		}
212	}
213	
214	// safeTargetNamePattern matches safe target names: alphanumeric, hyphens, underscores.
215	// Must start with a letter or digit.
216	var safeTargetNamePattern = regexp.MustCompile(`^[a-zA-Z0-9][a-zA-Z0-9_-]*$`)
217	
218	// ValidateTargetName checks that a target name is safe for use in filesystem paths.
219	// Rejects empty names, path traversal attempts, absolute paths, and special characters.
220	func ValidateTargetName(name string) error {
221		if name == "" {
222			return fmt.Errorf("target name must not be empty")
223		}
224		if name == DefaultTargetName {
225			return nil // The implicit default is always valid
226		}
227		if !safeTargetNamePattern.MatchString(name) {
228			return fmt.Errorf("target name %q contains unsafe characters (allowed: alphanumeric, hyphens, underscores)", name)
229		}
230		return nil
231	}
232	
233	// TargetStateFile returns the state file path for a target.
234	// The default target uses the legacy path; named targets use deploy-state-<name>.json.
235	func TargetStateFile(baseStateDir string, t Target) string {
236		if t.StateFile != "" {
237			return t.StateFile
238		}
239		if t.IsDefault() {
240			return filepath.Join(baseStateDir, DefaultStateFile)
241		}
242		return filepath.Join(baseStateDir, fmt.Sprintf("deploy-state-%s.json", t.Name))
243	}
244	
245	// TargetStagingDir returns the staging directory for a target.
246	// The default target uses the base staging dir; named targets use <staging>/<name>/.
247	func TargetStagingDir(baseStagingDir string, t Target) string {
248		if t.StagingDir != "" {
249			return t.StagingDir
250		}
251		if t.IsDefault() {
252			return baseStagingDir
253		}
254		return filepath.Join(baseStagingDir, t.Name)
255	}
256	
257	// TargetLockFile returns the lock file path for a target.
258	// The default target uses the legacy path; named targets use reconcile-<name>.lock.
259	func TargetLockFile(baseLockDir string, t Target) string {
260		if t.IsDefault() {
261			return filepath.Join(baseLockDir, "reconcile.lock")
262		}
263		return filepath.Join(baseLockDir, fmt.Sprintf("reconcile-%s.lock", t.Name))
264	}
