97	}
98	
99	// remoteComposeUpCmd returns the SSH command string for running docker compose up on a remote host.
100	func (d *DeployOps) remoteComposeUpCmd(composeDir string) string {
101		composeCmd := "docker compose"
102		if d.ProjectName != "" {
103			composeCmd = fmt.Sprintf("docker compose -p %s", d.ProjectName)
104		}
105		upArgs := "up -d"
106		if d.RemoveOrphans {
107			upArgs += " --remove-orphans"
108		}
109		return fmt.Sprintf("cd %s && %s %s", composeDir, composeCmd, upArgs)
110	}
111	
112	// DeployLocal syncs files locally using native Go file operations.
113	// Performs atomic copy: copies to temp directory first, then replaces target.
114	// Uses --delete semantics: removes files in target that don't exist in source.
115	func (d *DeployOps) DeployLocal(ctx context.Context, sourceDir, targetDir string, result *DeployResult) error {
116		start := time.Now()
117		logger := log.ComponentCtx(ctx, log.ComponentDeploy)
118	
119		if d.DryRun {
120			logger.Debug().
121				Str("source", sourceDir).
122				Str("target", targetDir).
123				Msg("Dry run: would deploy locally")
124			return nil
125		}
126	
127		logger.Debug().
128			Str(log.FieldOperation, "deploy_local").
129			Str("source", sourceDir).
130			Str("target", targetDir).
131			Msg("Deploying files locally")
132	
133		// Verify source directory exists
134		srcInfo, err := os.Stat(sourceDir)
135		if err != nil {
136			logger.Error().Err(err).Str("source", sourceDir).Msg("Source directory error")
137			return fmt.Errorf("source directory: %w", err)
138		}
139		if !srcInfo.IsDir() {
140			logger.Error().Str("source", sourceDir).Msg("Source is not a directory")
141			return fmt.Errorf("source is not a directory: %s", sourceDir)
142		}
143	
144		// Content-hash mode: compare per-file against existing target, skip unchanged.
145		if d.ContentHashSync {
146			if err := os.MkdirAll(targetDir, 0755); err != nil {
147				return fmt.Errorf("create target directory: %w", err)
148			}
149	
150			written, err := fileutil.CopyDirIfChanged(sourceDir, targetDir)
151			if err != nil {
152				return fmt.Errorf("copy with content hash: %w", err)
153			}
154	
155			// Remove files in target that aren't in source (--delete semantics).
156			if err := removeStaleFiles(ctx, sourceDir, targetDir); err != nil {
157				return fmt.Errorf("remove stale files: %w", err)
158			}
159	
160			if ctx.Err() != nil {
161				return ctx.Err()
162			}
163	
164			if result != nil {
165				result.AddWritten(written...)
166			}
167	
168			logger.Debug().
169				Str(log.FieldOperation, "deploy_local").
170				Str("target", targetDir).
171				Int("files_written", len(written)).
172				Int64(log.FieldDurationMS, time.Since(start).Milliseconds()).
173				Msg("Local deployment completed (content-hash sync)")
174			return nil
175		}
176	
177		// Standard mode: nuke-and-replace for atomic directory swap.
178		targetParent := filepath.Dir(targetDir)
179		if err := os.MkdirAll(targetParent, 0755); err != nil {
180			return fmt.Errorf("create target parent: %w", err)
181		}
182	
183		tmpDir, err := os.MkdirTemp(targetParent, ".deploy-tmp-*")
184		if err != nil {
185			return fmt.Errorf("create temp directory: %w", err)
186		}
187	
188		success := false
189		defer func() {
190			if !success {
191				_ = os.RemoveAll(tmpDir)
192			}
193		}()
194	
195		if err := fileutil.CopyDir(sourceDir, tmpDir); err != nil {
196			return fmt.Errorf("copy to temp: %w", err)
197		}
198	
199		if ctx.Err() != nil {
200			return ctx.Err()
201		}
202	
203		// Rename-aside pattern: move existing target out of the way, rename new
204		// into place, then clean up. This avoids the window where the target is
205		// missing (between remove and rename) that the old remove-then-rename
206		// approach had.
207		backupDir := targetDir + ".bak"
208		hadExisting := false
209	
210		// Guard against stale backup from a previous crash.
211		if _, err := os.Stat(backupDir); err == nil {
212			return fmt.Errorf("stale deploy backup exists at %s; restore or remove it before redeploying", backupDir)
213		} else if !os.IsNotExist(err) {
214			return fmt.Errorf("stat backup path: %w", err)
215		}
216	
217		if _, err := os.Stat(targetDir); err == nil {
218			hadExisting = true
219			if err := os.Rename(targetDir, backupDir); err != nil {
220				return fmt.Errorf("rename existing target aside: %w", err)
221			}
222		}
223	
224		if err := os.Rename(tmpDir, targetDir); err != nil {
225			logger.Error().Err(err).Str("target", targetDir).Msg("Failed to rename to target")
226			// Restore the backup so the original target is not lost.
227			if hadExisting {
228				if rbErr := os.Rename(backupDir, targetDir); rbErr != nil {
229					logger.Error().Err(rbErr).Msg("Failed to restore backup after rename failure")
230					return fmt.Errorf("rename to target failed: %w; restore backup from %s failed: %v", err, backupDir, rbErr)
231				}
232			}
233			return fmt.Errorf("rename to target: %w", err)
234		}
235	
236		if hadExisting {
237			if err := os.RemoveAll(backupDir); err != nil {
238				logger.Warn().Err(err).Str(log.FieldPath, backupDir).Msg("Deployment succeeded but backup cleanup failed")
239			}
240		}
241	
242		success = true
243		logger.Debug().
244			Str(log.FieldOperation, "deploy_local").
245			Str("target", targetDir).
246			Int64(log.FieldDurationMS, time.Since(start).Milliseconds()).
247			Msg("Local deployment completed")
248		return nil
249	}
250	
251	// removeStaleFiles removes files in targetDir that don't exist in sourceDir.
252	// Preserves --delete semantics when using per-file content-hash sync.
253	// Logs a warning for each file that cannot be removed and returns a summary
254	// error if any removals failed.
255	func removeStaleFiles(ctx context.Context, sourceDir, targetDir string) error {
256		logger := log.ComponentCtx(ctx, log.ComponentDeploy)
257		var removalErrors []error
258	
259		walkErr := filepath.WalkDir(targetDir, func(path string, d os.DirEntry, err error) error {
260			if err != nil {
261				return err
262			}
263	
264			relPath, err := filepath.Rel(targetDir, path)
265			if err != nil {
266				return err
267			}
268			if relPath == "." {
269				return nil
270			}
271	
272			srcPath := filepath.Join(sourceDir, relPath)
273			if _, err := os.Stat(srcPath); err != nil {
274				if !os.IsNotExist(err) {
275					return fmt.Errorf("stat source path %s: %w", relPath, err)
276				}
277				if d.IsDir() {
278					if rmErr := os.RemoveAll(path); rmErr != nil {
279						logger.Warn().Err(rmErr).Str(log.FieldPath, relPath).Msg("Failed to remove stale directory")
280						removalErrors = append(removalErrors, fmt.Errorf("remove directory %s: %w", relPath, rmErr))
281					}
282					return filepath.SkipDir
283				}
284				if rmErr := os.Remove(path); rmErr != nil {
285					logger.Warn().Err(rmErr).Str(log.FieldPath, relPath).Msg("Failed to remove stale file")
286					removalErrors = append(removalErrors, fmt.Errorf("remove file %s: %w", relPath, rmErr))
287				}
288			}
289			return nil
290		})
291	
292		if walkErr != nil {
293			return walkErr
294		}
295		if len(removalErrors) > 0 {
296			return fmt.Errorf("%d stale file(s) could not be removed: %w", len(removalErrors), errors.Join(removalErrors...))
297		}
298		return nil
299	}
300	
301	// DeployLocalFile syncs a single file locally using native Go file operations.
302	// Uses atomic copy via temp file. When ContentHashSync is enabled, skips writing
303	// if the file content has not changed.
304	func (d *DeployOps) DeployLocalFile(ctx context.Context, sourceFile, targetFile string, result *DeployResult) error {
305		if d.DryRun {
306			return nil
307		}
308	
309		if ctx.Err() != nil {
310			return ctx.Err()
311		}
312	
313		if d.ContentHashSync {
314			changed, err := fileutil.CopyFileIfChanged(sourceFile, targetFile)
315			if err != nil {
316				return err
317			}
318			if changed && result != nil {
319				// Use Base() so the path is relative (matches CopyDirIfChanged).
320				// The caller prefixes with the target's RelPath via PrefixLatest.
321				result.AddWritten(filepath.Base(targetFile))
322			}
323			return nil
324		}
325	
326		return fileutil.CopyFile(sourceFile, targetFile)
327	}
