319	// composePSEntry represents a single container from `docker compose ps --format json`.
320	// Docker Compose v2 emits one JSON object per line (NDJSON).
321	type composePSEntry struct {
322		Name   string `json:"Name"`
323		State  string `json:"State"`
324		Health string `json:"Health"`
325	}
326	
327	// classifyComposePS inspects parsed `docker compose ps` output to classify the
328	// failure. Each container is categorized as running-healthy, running-unhealthy,
329	// or failed (exited/restarting/dead/absent).
330	//
331	// Returns failureUnhealthyOnly when every container is running (some unhealthy).
332	// Returns failureStartFailure when any container is not running.
333	func classifyComposePS(entries []composePSEntry) composeFailureResult {
334		var unhealthy []string
335		var failed []string
336	
337		for _, e := range entries {
338			switch strings.ToLower(e.State) {
339			case "running":
340				health := strings.ToLower(e.Health)
341				if health == "unhealthy" || health == "starting" {
342					unhealthy = append(unhealthy, e.Name)
343				}
344				// "healthy" or "" (no healthcheck) are fine
345			default:
346				// exited, restarting, dead, created, paused, removing, etc.
347				failed = append(failed, e.Name)
348			}
349		}
350	
351		if len(failed) > 0 {
352			return composeFailureResult{Kind: failureStartFailure, Unhealthy: unhealthy, Failed: failed}
353		}
354		if len(unhealthy) > 0 {
355			return composeFailureResult{Kind: failureUnhealthyOnly, Unhealthy: unhealthy, Failed: failed}
356		}
357		// All containers running and healthy but compose still exited non-zero.
358		return composeFailureResult{Kind: failureStartFailure}
359	}
360	
361	// parseComposePSOutput parses output from `docker compose ps --format json`.
362	// Handles both JSON array format (Docker Compose docs spec) and NDJSON
363	// (one JSON object per line, emitted by Compose v2.21.0+).
364	func parseComposePSOutput(output []byte) ([]composePSEntry, error) {
365		trimmed := strings.TrimSpace(string(output))
366		if trimmed == "" {
367			return nil, nil
368		}
369	
370		// JSON array format: [{...},{...}]
371		if strings.HasPrefix(trimmed, "[") {
372			var entries []composePSEntry
373			if err := json.Unmarshal([]byte(trimmed), &entries); err != nil {
374				return nil, err
375			}
376			if len(entries) == 0 {
377				return nil, nil
378			}
379			return entries, nil
380		}
381	
382		// NDJSON format: one JSON object per line
383		var entries []composePSEntry
384		lines := strings.Split(trimmed, "\n")
385		for _, line := range lines {
386			line = strings.TrimSpace(line)
387			if line == "" {
388				continue
389			}
390			var entry composePSEntry
391			if err := json.Unmarshal([]byte(line), &entry); err != nil {
392				return nil, err
393			}
394			entries = append(entries, entry)
395		}
396	
397		return entries, nil
398	}
